<script lang="ts">
	import type { CategoryId, Transaction } from '$lib/types';
	import { buildInsights, dailyCumulativeExpenses, shiftMonthKey, type Insight } from '$lib/insights';
	import { getMerchantCategoryMap } from '$lib/store.svelte';
	import { formatEURCompact } from '$lib/format';

	/**
	 * Dashboard Insights card: 2-3 insights generated by local rules (icon + text) and a mini chart of
	 * the current month's cumulative spending (solid teal) over the previous month (neutral dashes).
	 */
	let {
		transactions,
		overrides,
		budgets,
		monthKey,
		cutoffDay = null,
		projection = null,
		showList = true,
		showChart = true,
		showReportLink = true,
		fill = null
	}: {
		transactions: Transaction[];
		overrides: Record<string, CategoryId>;
		budgets: Partial<Record<CategoryId, number>>;
		monthKey: string;
		/** Current month: cutoff day (comparisons at the same day of the previous month). */
		cutoffDay?: number | null;
		/** End-of-month projection of the balance chart (current accounts). */
		projection?: { balance: number; endIso: string } | null;
		/** Analysis sentences (block element). */
		showList?: boolean;
		/** Mini chart: this month vs last month (block element). */
		showChart?: boolean;
		/** « Rapport du mois » button (block element). */
		showReportLink?: boolean;
		/** Height left to the card in its tile when the tile height is set: the mini chart takes the rest. */
		fill?: number | null;
	} = $props();

	const insights = $derived(buildInsights(transactions, overrides, budgets, monthKey, getMerchantCategoryMap(), { cutoffDay, projection }).slice(0, 3));

	// Cumulative series aligned on the day of the month (x = 1..31), current month truncated to today
	const current = $derived.by(() => {
		const full = dailyCumulativeExpenses(transactions, monthKey, overrides, getMerchantCategoryMap());
		return cutoffDay ? full.slice(0, cutoffDay) : full;
	});
	const previous = $derived(dailyCumulativeExpenses(transactions, shiftMonthKey(monthKey, -1), overrides, getMerchantCategoryMap()));

	/** Measured sizes: the chart is drawn at its real pixel size (text never scaled with the tile). */
	let chartWidth = $state(0);
	let above = $state(0);
	let legend = $state(0);
	const W = $derived(chartWidth > 0 ? Math.max(120, chartWidth - 64) : 300);
	const H = $derived(fill === null ? 120 : Math.max(70, Math.floor(fill - above - legend - 31)));
	const PAD = 4;

	/** Builds an SVG path for a cumulative series (normalised on H). */
	function buildPath(values: number[], max: number, days: number): string {
		if (values.length === 0 || max <= 0) return '';
		const w = W - PAD * 2;
		const h = H - PAD * 2;
		return values
			.map((v, i) => {
				const x = PAD + (i / Math.max(days - 1, 1)) * w;
				const y = PAD + (1 - v / max) * h;
				return `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
			})
			.join(' ');
	}

	const days = $derived(Math.max(current.length, previous.length));
	const chartMax = $derived(Math.max(current[current.length - 1] ?? 0, previous[previous.length - 1] ?? 0));
	const currentPath = $derived(buildPath(current, chartMax, days));
	const previousPath = $derived(buildPath(previous, chartMax, days));

	/** Last point of a series (for the value label at the end of the curve). */
	function endPoint(values: number[]): { x: number; y: number; v: number } | null {
		if (values.length === 0 || chartMax <= 0) return null;
		const i = values.length - 1;
		const v = values[i]!;
		return { x: PAD + (i / Math.max(days - 1, 1)) * (W - PAD * 2), y: PAD + (1 - v / chartMax) * (H - PAD * 2), v };
	}
	const currentEnd = $derived(endPoint(current));
	const previousEnd = $derived(endPoint(previous));

	/** Dot colour from the insight tone. */
	function toneColor(tone: Insight['tone']): string {
		return tone === 'teal' ? 'var(--accent)' : tone === 'amber' ? 'var(--amber)' : 'var(--text-secondary)';
	}
</script>

<div class="flow-root" bind:clientHeight={above}>
	{#if showList && insights.length > 0}
		<ul class="my-auto space-y-2 py-2">
			{#each insights as insight (insight.id)}
				<li class="flex items-start gap-3">
					<span class="mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center" style="color: {toneColor(insight.tone)};" aria-hidden="true">
						<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
							{#if insight.icon === 'trend'}
								<path d="M3 17l5-6 4 4 6-8" />
								<path d="M15 7h6v6" />
							{:else if insight.icon === 'projection'}
								<path d="M4 16l4-5 4 3 8-9" />
								<path d="M4 20h16" opacity="0.5" />
							{:else if insight.icon === 'budget'}
								<circle cx="12" cy="12" r="8.5" />
								<path d="M12 3.5a8.5 8.5 0 0 1 8.5 8.5" stroke-width="3.2" />
							{:else}
								<path d="M6 3h12v18l-3-2-3 2-3-2-3 2V3z" />
								<path d="M9.5 8.5h5M9.5 12.5h5" />
							{/if}
						</svg>
					</span>
					<p class="min-w-0 flex-1 text-[13px] leading-snug text-secondary">
						{insight.text}
					</p>
				</li>
			{/each}
		</ul>
	{/if}

	<!-- Link to the monthly report -->
	{#if showReportLink}
	<div class="{(showList && insights.length > 0) || (showChart && chartMax > 0) ? 'mt-3' : 'my-auto'}">
		<a href="/rapport" class="btn btn-accent btn-sm">Rapport du mois</a>
	</div>
	{/if}
</div>

<!-- Mini chart: cumulative spending this month (solid teal) vs last month (neutral dashes) -->
{#if showChart && chartMax > 0}
	<div class="mt-3 border-t pt-3" style="border-color: var(--border-subtle);" bind:clientWidth={chartWidth}>
		<div class="mb-1.5 flex flex-wrap items-center gap-x-4 gap-y-1 text-[11px] text-secondary" bind:clientHeight={legend}>
			<span class="flex items-center gap-1.5">
				<span class="inline-block h-0.5 w-4 rounded-full" style="background-color: var(--accent);"></span>
				Ce mois
			</span>
			<span class="flex items-center gap-1.5">
				<span class="inline-block w-4 border-t-2 border-dashed" style="border-color: var(--text-secondary);"></span>
				Mois dernier
			</span>
		</div>
		<!-- Right margin reserved for value labels at the end of the curves -->
		<svg width={W + 64} height={H} viewBox="0 0 {W + 64} {H}" class="block max-w-full" role="img" aria-label="Dépenses cumulées : mois courant vs mois précédent">
			{#if previousPath}
				<path
					d={previousPath}
					fill="none"
					stroke="var(--text-secondary)"
					stroke-width="1.6"
					stroke-dasharray="4 4"
					stroke-linecap="round"
					opacity="0.7"
				/>
			{/if}
			{#if currentPath}
				<path d={currentPath} fill="none" stroke="var(--accent)" stroke-width="2" stroke-linecap="round" />
			{/if}
			<!-- Direct values at the end of the curves: the chart states a number, not just a shape -->
			{#if previousEnd}
				<text x={previousEnd.x + 6} y={previousEnd.y + (currentEnd && Math.abs(currentEnd.y - previousEnd.y) < 12 ? 12 : 4)} font-size="11" fill="var(--text-secondary)">{formatEURCompact(previousEnd.v)}</text>
			{/if}
			{#if currentEnd}
				<text x={currentEnd.x + 6} y={currentEnd.y + 4} font-size="11" font-weight="600" fill="var(--accent)">{formatEURCompact(currentEnd.v)}</text>
			{/if}
		</svg>
	</div>
{/if}
